<?php $bounty=$thread['bounty']??null;$owner=$me && (int)$me['id']===(int)$item['author_id'];if(!$bounty && (!$owner || !$s->enabled('bounties') || (int)$thread['accepted_comment_id'])){return;} ?>
<section class="bounty-panel" data-bounty><div class="row"><span class="quick-icon"><?= icon('gift') ?></span><div class="grow"><span class="eyebrow">A THANK-YOU, WITH PURPOSE</span><h3><?= t('Question bounty') ?></h3></div><?php if($bounty): ?><span class="bounty-amount"><?= (int)$bounty['amount'] ?><small><?= t('Points') ?></small></span><?php endif ?></div>
<?php if($bounty): ?><p><?= t(['open'=>'Points are held securely until one answer is accepted.','awarded'=>'This bounty has been awarded. The payment cannot be reassigned.','returned'=>'The held points were returned to the question author.'][$bounty['status']]) ?></p><div class="row wrap"><span class="pill"><?= t($bounty['status']) ?></span><span class="hint"><?= t('Deadline') ?>: <?= dt((int)$bounty['expires_at'],'Y.m.d H:i') ?></span><?php if($owner && $bounty['status']==='open' && (int)$bounty['expires_at']<=time()): ?><?= form_start('bounty_release') . hidden('content_id',$item['id']) ?><?php button('Return expired bounty','secondary small','refresh'); ?></form><?php endif ?></div>
<?php else: ?><details><summary><?= t('Offer points for a helpful answer') ?></summary><?= form_start('bounty_fund') . hidden('content_id',$item['id']) ?><div class="form-grid"><?php field('amount','Bounty points',100,'number',['required'=>'required','min'=>'1','max'=>(string)$s->get('bounty_max')]);field('days','Answering period (days)',7,'number',['required'=>'required','min'=>'1','max'=>'30']); ?></div><p class="hint"><?= t('Points are deducted now and awarded once on acceptance. You cannot award yourself. Unanswered expired bounties can be returned.') ?></p><?php button('Fund question bounty','','gift'); ?></form></details><?php endif ?></section>
